WITH matched_keys AS (SELECT store_id, product_id FROM store_sales INTERSECT SELECT store_id, product_id FROM store_sales WHERE sale_date < '2023-06-04'), verified AS (SELECT s.* FROM store_sales s INNER JOIN matched_keys k ON s.store_id = k.store_id AND s.product_id = k.product_id) SELECT id, store_id, product_id, sale_date, units FROM verified ORDER BY product_id DESC NULLS LAST;
